const WARRIOR_RULES_VERSION=3;
function migrateWarriorRules(h){
  if(h?.role!=='warrior'||h.warriorRulesVersion>=WARRIOR_RULES_VERSION)return h;
  const migrateCards=list=>{if(!Array.isArray(list))return list;let parries=0,critical=0;return list.map(card=>card==='parry'&&parries++<3?(parries<3?'charge':'shield_protection'):card==='critical'&&critical++<1?'sword':card)};
  h.deck=migrateCards(h.deck);h.collection=migrateCards(h.collection);
  const zones=[h.hand,h.draw,h.discard],migrated=migrateCards(zones.flatMap(zone=>Array.isArray(zone)?zone:[]));let offset=0;
  for(const zone of zones)if(Array.isArray(zone)){zone.splice(0,zone.length,...migrated.slice(offset,offset+zone.length));offset+=zone.length}
  h.handSlots=null;
  if(h.talents&&h.warriorRulesVersion<3){h.talents.improved_taunt=Math.max(h.talents.improved_taunt||0,h.talents.improved_charge||0);h.talents.improved_charge=0;h.talents.cleave=0;h.talents.improved_critical=0}
  h.abilities=[...new Set([...(h.abilities||[]).filter(card=>card!=='parry'),'charge','shield_protection'])];
  h.warriorRulesVersion=WARRIOR_RULES_VERSION;
  return h;
}
