function effectiveLootTier(g,boxTier){const m={heroic:{BRONZE:'SILVER',SILVER:'GOLD',GOLD:'GOLD'},hardcore:{BRONZE:'GOLD',SILVER:'GOLD',GOLD:'GOLD2'}}[g&&g.difficulty];return m&&m[boxTier]||boxTier}
