function enemyLabel(e){if(e.label)return e.label;const label=ENEMY_DEFINITIONS[e.type]?.label;return label?label(e):`Nemico ${e.id}`}
function aliveFighters(g){return g.enemies.filter(e=>e.hp>0&&!['fungus','engineerBomb'].includes(e.type))}
