function fungusHit(g,target,power){if(target.hp<=0)return 0;const{hit,prevented}=preventHeroDamage(target,power);target.hp-=hit;g.telemetry.classContribution[target.role].prevention+=prevented;g.telemetry.classContribution[target.role].damageTaken+=hit;if(target.hp<=0)g.telemetry.deaths[target.role]=(g.telemetry.deaths[target.role]||0)+1;return hit}
function fungusSpawnCells(g){const rows=Math.max(4,Math.min(8,+g.combatGridRows||4)),cols=Math.max(6,Math.min(10,+g.combatGridCols||6)),occupied=new Set([...g.party,...g.enemies,...(g.combatGridCustomChests||[])].map(piece=>piece.combatGridPos||piece).filter(pos=>pos.row&&pos.col).map(pos=>`${pos.row}:${pos.col}`)),cells=[];for(let col=cols-1;col>=Math.ceil(cols/2);col--)for(let row=1;row<=rows;row++)if(!occupied.has(`${row}:${col}`))cells.push({row,col});return cells}
function fungusTargets(g,fungus){if(window.combatGridEnemyPatternHeroes)return window.combatGridEnemyPatternHeroes(g,fungus,'spores');const origin=fungus.combatGridPos;if(!origin)return[];return aliveHeroes(g).filter(hero=>hero.combatGridPos&&Math.abs(hero.combatGridPos.row-origin.row)+Math.abs(hero.combatGridPos.col-origin.col)===1)}
function maybeSpawnFungi(g){const cfg=fungusConfig(g);if(!g.playerBoardEnabled||!cfg||g.fungiState)return;const room=currentExplorationRoom(g.exploration);if(!room||!(room.heroExitTreasure>0))return;g.fungiState='active';g.fungiCharge=0;const base=Math.max(0,...g.enemies.map(e=>e.id)),cells=fungusSpawnCells(g),hp=difficultyEnemyHp(g,FUNGUS_HP);for(let i=1;i<=FUNGUS_COUNT;i++)g.enemies.push({id:base+i,type:'fungus',hp,maxHp:hp,damage:0,draw:[],discard:[],bleeds:[],bleedCount:0,taunted:false,combatGridPos:cells[i-1]});boardAudit(g,'FUNGI_SPAWNED',{count:FUNGUS_COUNT,room:room.id,hp});note(g,`🍄 L’Overlord gioca Funghi del Miasma: ${FUNGUS_COUNT} funghi da ${hp} HP spuntano dal fango e colpiscono le 4 caselle ortogonali.`)}
function resolveFungiTurn(g){const cfg=fungusConfig(g),fungi=aliveFungi(g);if(!cfg||!fungi.length)return;let total=0;for(const f of fungi)for(const h of fungusTargets(g,f))total+=fungusHit(g,h,cfg.tick);note(g,`🍄 ${fungi.length} Funghi del Miasma emanano spore nelle 4 caselle ortogonali: ${total} danni totali.`);g.fungiCharge=(g.fungiCharge||0)+1;if(g.fungiCharge>=FUNGUS_FUSE){const targets=[...new Set(fungi.flatMap(f=>fungusTargets(g,f)))];let boom=0;for(const h of targets)boom+=fungusHit(g,h,cfg.boom);note(g,`💥 I Funghi del Miasma esplodono: ${cfg.boom} danni agli Eroi nelle 4 caselle ortogonali (${boom} danni totali).`);let woundedFungi=0;if(g.difficulty==='hardcore'){for(const h of targets){h.deck.push('wound','wound');h.draw.push('wound','wound');woundedFungi++}if(woundedFungi)note(g,`☣ In Hardcore l’esplosione conficca 2 Ferite nel mazzo di ogni Eroe colpito.`)}boardAudit(g,'FUNGI_EXPLODED',{damage:cfg.boom,targets:targets.length,woundsPerHero:g.difficulty==='hardcore'?2:0});g.enemies=g.enemies.filter(e=>e.type!=='fungus');g.fungiState='done';g.fungiCharge=0}}
