const imageAsset=path=>path?.startsWith('assets/optimized/')?path:path?.replace(/^assets\//,'assets/optimized/').replace(/\.(jpeg|png)$/i,'.webp')||path;
const ENEMY_ART=Object.fromEntries(Object.entries(ENEMY_DEFINITIONS).map(([type,definition])=>[type,imageAsset(definition.art)]));
function weaponArt(h,slot){const m={warrior:['sword','shield'],healer:['staff-priest','wand-priest'],rogue:['dagger-left','dagger-right'],mage:['staff-mage','wand-mage'],paladin:['sword','shield'],warlock:['staff-mage','wand-mage']};return (m[h.role]||['sword','shield'])[slot]};
const noteBeforeTheme=note;
note=function(g,message){const themed=String(message).replace(/Mini Boss(?: \d+)?/g,'Grum’Arat, Strega del Miasma').replace(/Goblin Ingegnere (\d+)/g,(_,id)=>enemyLabel(g.enemies.find(e=>e.id===+id)||{id,type:'engineer'})).replace(/Goblin (\d+)/g,(_,id)=>enemyLabel(g.enemies.find(e=>e.id===+id)||{id,type:'goblin'})).replace(/(\d+) Goblin\b/g,(_,count)=>`${count} ${+count===1?'Razziatore':'Razziatori'}`).replace(/\bServitori\b/g,'Girini Putrescenti').replace(/\bServitore\b/g,'Girino Putrescente');return noteBeforeTheme(g,themed)};
const RAID_LEVELS=[{id:'normale',label:'Normale',sub:'HP e danni standard',expectedLevel:9,expectedBuild:'~4 ricompense · Tier 2 accessibile',hpScale:1,damageScale:1,fungi:null},{id:'heroic',label:'Heroic',sub:'+50% HP · +60% danni · Funghi del Miasma',expectedLevel:12,expectedBuild:'~7 ricompense totali · Capstone accessibile',hpScale:1.5,damageScale:1.6,fungi:{tick:1,boom:5}},{id:'hardcore',label:'Hardcore',sub:'+100% HP · +125% danni · Funghi potenziati',expectedLevel:13,expectedBuild:'~8 ricompense totali · Build avanzata',hpScale:2,damageScale:2.25,fungi:{tick:2,boom:8}}];
function raidLevelIndex(id){const i=RAID_LEVELS.findIndex(l=>l.id===id);return i<0?0:i}
