function enemyActionDamage(g,type,action){const cfg=enemyAction(type,action),damage=cfg.damage||0;return cfg.scales===false?damage:difficultyEnemyDamage(g,damage)}
function enemyActionDescription(g,type,action,enemy=null){const cfg=enemyAction(type,action),damage=enemyActionDamage(g,type,action),damageType=ENEMY_DAMAGE_LABEL[cfg.damageType]||'';if(action==='spores')return`Spore ed esplosione infliggono danni ${damageType} nelle 4 caselle ortogonali al Fungo.`;if(action==='attack'||action==='minion_attack')return`Attacco: ${damage} ${damage===1?'danno':'danni'} ${damageType} a un Eroe nella sagoma.`;if(cfg.heal)return`${cfg.name}: cura ${cfg.heal} HP a se stesso o a un nemico ferito nella sagoma.`;if(cfg.split)return`${cfg.name}: ${damage} danni ${damageType} divisi tra tutti gli Eroi sulla linea ortogonale.`;if(cfg.wounds)return`Tactic: ${damage} danni ${damageType} e ${cfg.wounds} ${cfg.wounds===1?'Wound':'Wound'} a un Eroe nella sagoma.`;if(type==='engineer'&&action==='special')return`${cfg.name}: lancia nella sagoma una carta da ${cfg.bombHp} HP; se sopravvive esplode al prossimo turno Overlord e infligge ${damage} danni ${damageType} nelle 8 caselle adiacenti.`;if(cfg.longCast)return enemy?.megaBombCasting?`${cfg.name}: completa il Cast Lungo e infligge ${damage} danni ${damageType} a tutti gli Eroi nella sagoma.`:`${cfg.name}: Cast Lungo; la seconda carta infligge ${damage} danni ${damageType} a tutti gli Eroi nella sagoma.`;return`${cfg.name||'Special'}: ${damage} danni ${damageType} a tutti gli Eroi nella sagoma.`}
function enemyRulesSummary(g){const types=[...new Set(aliveFighters(g).map(enemy=>enemy.type))];return(types.length?types:['goblin']).map(type=>{const definition=ENEMY_DEFINITIONS[type],actions=Object.keys(definition.actions).filter(action=>action!=='minion_attack'),movement=enemyMovement(type);return`<strong>${definition.gridName}</strong> · Movimento ${movement.steps} casella${movement.steps===1?'':'e'} quando non può agire. ${actions.map(action=>enemyActionDescription(g,type,action)).join(' ')}`}).join('<br>')}
const TUTORIAL_ROOMS=4,TUTORIAL_ROOM_NAMES=['Sentiero Fangoso','Rovine della Palude','Nebbia Tossica','Soglia del Dungeon'];
// Arte tile mappa per zona tutorial (per profondità); indice mancante => fallback a ROOM_ART[tileId].
const TUTORIAL_ROOM_ART=['assets/sentiero-fangoso.jpeg','assets/rovine-della-palude.jpeg'].map(imageAsset);
