const TUTORIAL_START_DECK={warrior:['charge','charge'],rogue:['backstab','backstab'],mage:['fireball','fireball'],healer:['divine_strike','divine_strike']};
function tutorialQueueFor(role){return TUTORIAL_ZONE_GRANTS.flatMap(z=>z[role]||[])}
// Fine zona: riassume le carte guadagnate salendo di livello in questa stanza, mostra popup, tiene in attesa.
// Fine zona: ogni eroe sale di livello (+1 HP) e riceve le carte della zona appena completata.
// zoneIdx = (stanze esplorate)-1. Conteggio carte variabile per zona (es. War 3 parata in zona 2).
function grantTutorialZoneCards(g){const zoneIdx=(g.exploration?.roomsExplored||1)-1;if(g._grantedZoneIdx===zoneIdx){g.state='tutorial_gate';return}g._grantedZoneIdx=zoneIdx;const grant=TUTORIAL_ZONE_GRANTS[zoneIdx]||{},summary=[];for(const h of aliveHeroes(g)){h.heroLevel++;h.maxHp+=1;h.hp+=1;g.telemetry.progression.levelUps[h.role]++;const cards=grant[h.role]||[];if(cards.length){h.deck.push(...cards);h.draw=shuffle([...(h.draw||[]),...cards])}summary.push({role:h.role,cards})}g._tutorialZoneSummary=summary;g.state='tutorial_gate';g._tutorialZonePopup=true;boardAudit(g,'TUTORIAL_ZONE_CLEARED',{zone:zoneIdx+1,grant})}
function tutorialAdvanceZone(g){const room=currentExplorationRoom(g.exploration),exitId=room&&room.exits&&room.exits[0]&&room.exits[0].id;g._tutorialZonePopup=false;g.state='exit_choice';g.pendingExitChoice=true;if(exitId)choosePlayerExit(g,exitId);else{g.state='playing';startEncounter(g)}}
function applyPlayerBoardEnemyStats(g){if(g.tutorial&&g.encounter===0&&g.enemies.some(e=>e.hp>0)&&g.enemies.length!==2){g.enemies=[1,2].map(id=>({id,type:'snake',hp:8,maxHp:8,damage:enemyBaseAttack('snake'),draw:shuffle(CONFIG.goblin.deck),discard:[],bleeds:[],bleedCount:0,taunted:false}))}const tokens=g.exploration?currentExplorationRoom(g.exploration)?.fighters||[]:[],fighters=g.enemies.filter(e=>e.type!=='miniBoss'&&e.type!=='miniMob');fighters.forEach((e,index)=>{if(g.tutorial)e.type='snake';else if(tokens[index])e.type=ENEMY_TYPE_BY_TOKEN[tokens[index]]||'goblin'});for(const e of g.enemies){const cfg=PLAYER_BOARD_ENEMIES[e.type];if(!cfg)continue;e.hp=e.maxHp=difficultyEnemyHp(g,cfg.hp);e.damage=enemyBaseAttack(e.type);e.megaBombCasting=false;e.casting=null;e.summonThresholdsTriggered=[]}if(g.tutorial&&g.encounter===1){if(!g.enemies.length)g.enemies=[{id:1,type:'snake',draw:shuffle(CONFIG.goblin.deck),discard:[],bleeds:[]}];g.enemies.length=1;const m=g.enemies[0];m.id=1;m.type='snake';m.label=TUTORIAL_ZONE2_MOB;m.art='assets/ragno-gigante.jpeg';m.hp=m.maxHp=12;m.damage=enemyBaseAttack('snake');m.bleedCount=0;m.taunted=false;m.megaBombCasting=false;m.casting=null}else if(g.tutorial&&g.encounter===2){g.enemies=[1,2].map(id=>({id,type:'snake',label:`${TUTORIAL_ZONE3_MOB} ${id}`,art:'assets/ragno-gigante.jpeg',hp:6,maxHp:6,damage:enemyBaseAttack('snake'),draw:shuffle(CONFIG.goblin.deck),discard:[],bleeds:[],bleedCount:0,taunted:false,megaBombCasting:false,longCast:false,casting:null,summonThresholdsTriggered:[]}))}}
function xpThreshold(h,g=game){const curve=Math.max(0,h.heroLevel-5);return g?.tutorial&&h.heroLevel===1?5:3+h.heroLevel+curve*(curve+1)/2}
function grantKillXp(g,enemy){if(!g.playerBoardEnabled||['fungus','engineerBomb'].includes(enemy.type))return;g.telemetry.progression.kills++;if(g.tutorial)return;let xp=g.tutorial&&enemy.type==='snake'?HERO_TUTORIAL_SNAKE_XP:enemy.type==='miniBoss'?HERO_MINIBOSS_KILL_XP:enemy.type==='miniMob'?HERO_MINIMOB_KILL_XP:HERO_KILL_XP;if(g.xpHalved)xp=Math.max(1,Math.round(xp/2));for(const h of aliveHeroes(g)){const threshold=xpThreshold(h,g);if(!threshold)continue;h.xp+=xp;g.telemetry.progression.xpGranted[h.role]+=xp;boardAudit(g,'XP_GAINED',{hero:h.role,enemyId:enemy.id,enemyType:enemy.type,value:xp,xp:h.xp,threshold});if(h.xp>=threshold){const from=h.heroLevel;h.heroLevel++;h.xp-=threshold;const _inc=g.tutorial?1:2;h.maxHp+=_inc;h.hp+=_inc;g.telemetry.progression.levelUps[h.role]++;if(g.tutorial){const add=(h.tutorialQueue||[]).splice(0,2);if(add.length){h.deck.push(...add);h.draw=shuffle([...(h.draw||[]),...add]);(g._tutorialZoneGained||(g._tutorialZoneGained={}))[h.role]=[...(g._tutorialZoneGained[h.role]||[]),...add]}}else h.pendingLevelRewards++;boardAudit(g,'HERO_LEVEL_UP',{hero:h.role,from,to:h.heroLevel,maxHp:h.maxHp,nextThreshold:xpThreshold(h,g)});note(g,g.tutorial?`⬆ ${NAMES[h.role]} livello ${h.heroLevel}: +1 HP · mazzo ${h.deck.length}/10.`:`⬆ ${NAMES[h.role]} raggiunge il livello ${h.heroLevel}: +2 HP e ricompensa talento/carta a fine combattimento.`)}}}
function nextAdvancementReward(h){const source=h.advancementQueue?.shift();return source?{hero:h,ability:h.abilities[Math.floor(Math.random()*h.abilities.length)],source}:null}
function advancementRewards(g){return aliveHeroes(g).map(h=>{h.advancementQueue=Array(h.pendingLevelRewards||0).fill('level');h.pendingLevelRewards=0;return nextAdvancementReward(h)}).filter(Boolean)}
function resetHeroTurn(g){g.turnOrder=(g.selectedRoles?.length?g.selectedRoles:g.party.map(h=>h.role));g.activeTurnIndex=0;while(g.activeTurnIndex<g.turnOrder.length&&!aliveHeroes(g).some(h=>h.role===g.turnOrder[g.activeTurnIndex]))g.activeTurnIndex++;g.activeRole=g.turnOrder[g.activeTurnIndex]||null}
function advanceHeroTurn(g){if(!g.playerBoardEnabled||g.state==='restoring')return;if(g.state!=='playing'||g.activeRole==='overlord')return;const current=g.party.find(h=>h.role===g.activeRole);if(current?.actions>0||current?.preparationPending||current?.evasionFreeFlip)return;g.initIndex++;activateInitiativeSlot(g)}
// INIZIATIVA: classifica persistente (eroi + 'overlord') interlacciata. Vedi handoff. Il bench/full-auto (endRound 300) resta a blocchi, non interlaccia.
function startInitiativeRound(g){if(!g.initiative)g.initiative=[...(g.selectedRoles||g.party.map(h=>h.role)),'overlord'];g.initIndex=0;activateInitiativeSlot(g)}
function heroHasResRune(h){return (h?.bag||[]).some(s=>s?.item==='resurrection_rune'&&s.count>0)}
function activateInitiativeSlot(g){if(g.state!=='playing')return;while(g.initIndex<g.initiative.length){const tok=g.initiative[g.initIndex];if(tok==='overlord')return prepareManualOverlordTurn(g);const hero=g.party.find(h=>h.role===tok);if(hero&&(hero.hp>0||heroHasResRune(hero))){g.activeRole=tok;note(g,hero.hp>0?`▶ Turno ${NAMES[tok]}.`:`✝ ${NAMES[tok]} è a terra: usa la Runa o passa.`);setTimeout(()=>{if(game===g&&!g.pendingInitialInitiative&&!g.tutorial&&g.state==='playing'&&g.activeRole===tok&&!aiControls(g,tok))showTurnAnnounce(tok)},g.aiOverlordCue?1600:0);return}g.initIndex++}endRoundBoard(g)}
function advanceAfterOverlord(g){const finish=()=>{g.overlordTurn=null;g.showFriendly=false;delete g._overlordFxEnemyId;automaticEnemyTarget(g);if(g.state!=='playing')return;g.initIndex++;activateInitiativeSlot(g)};const cue=g.aiOverlordCue,offensive=cue?.roles?.length&&cue.move!=='RIPARAZIONE'&&cue.move!=='PREPARA MEGA BOMBA';if(g===game&&offensive&&!g.benchmarkMode){g._overlordExitPending=true;setTimeout(()=>{if(!g._overlordExitPending)return;g._overlordExitPending=false;finish();render()},1500);return}finish()}
function endRoundBoard(g){if(g.state!=='playing')return;g.round++;maybeSpawnFungi(g);if(g.tauntMode==='round')g.enemies.forEach(e=>{if(e.tauntExpiresRound<=g.round){e.taunted=false;e.tauntExpiresRound=null}});g.party.forEach(h=>{h.actions=CONFIG.actionsPerRound;h.shield=0;h.guardBlock=0;h.counter=0;refill(h,g)});g.initIndex=0;note(g,`▶ Round ${g.round}.`);activateInitiativeSlot(g)}
// riordino tra stanze: primo->ultimo (rotazione, preserva l'ordine relativo), poi l'Overlord scivola di 1 verso l'inizio (ultima parola). ponytail: nudge Overlord placeholder aggressivo; sostituire con euristica AI in Fase 2.
function roomTransitionInitiative(g){if(!g.initiative||g.fixedInitiative){delete g.initiativeShift;return}const before=[...g.initiative],first=g.initiative.shift();g.initiative.push(first);g.initiativeShift={before,after:[...g.initiative],first,overlordAdvanced:false};boardAudit(g,'INITIATIVE_ROOM_SHIFT',{before,order:[...g.initiative],first})}
function moveInitiativeLater(g,role){if(g.state!=='playing'||g.activeRole!==role)return false;const h=g.party.find(x=>x.role===role);if(!h||h.actions<1)return false;const i=g.initIndex;if(g.initiative[i]!==role||i>=g.initiative.length-1)return false;[g.initiative[i],g.initiative[i+1]]=[g.initiative[i+1],g.initiative[i]];h.actions--;boardAudit(g,'INITIATIVE_DELAY',{hero:role,order:[...g.initiative]});note(g,`↓ ${NAMES[role]} ritarda di un posto (1 azione).`);activateInitiativeSlot(g);return true}
