function moveInitiativeEarlier(g,role){if(g.state!=='playing'||g.activeRole!==role)return false;const h=g.party.find(x=>x.role===role);if(!h||h.actions<1)return false;const i=g.initIndex;if(g.initiative[i]!==role||i<=0)return false;[g.initiative[i],g.initiative[i-1]]=[g.initiative[i-1],g.initiative[i]];h.actions--;boardAudit(g,'INITIATIVE_ADVANCE',{hero:role,order:[...g.initiative]});note(g,`↑ ${NAMES[role]} guadagna iniziativa: sale di un posto (1 azione).`);return true}
function initiativeTrackHtml(g){if(!g.initiative)return'';return`<div class="init-track"><b>Iniziativa</b>${g.initiative.map((tok,i)=>{const cur=g.state==='playing'&&tok===g.activeRole,dead=tok!=='overlord'&&!g.party.some(h=>h.role===tok&&h.hp>0),hero=g.party.find(h=>h.role===tok),art=heroThumbArt(tok,hero);return`<span class="init-chip role-${tok} ${tok==='overlord'?'ov':''} ${cur?'current':''} ${dead?'dead':''}" title="${i+1}. ${tok==='overlord'?'Overlord':NAMES[tok]}" aria-label="${i+1}. ${tok==='overlord'?'Overlord':NAMES[tok]}"><img src="${art}" alt=""><small>${i+1}</small></span>`}).join('')}</div>`}
function passHeroTurn(g){const h=g.party.find(hero=>hero.role===g.activeRole);if(!h||g.state!=='playing')return false;while(normalizePreparation(h)){const index=h.hand.findIndex(preparationDiscardable);if(index<0)break;discardPreparation(g,h,index)}h.preparationPending=0;h.actions=0;h.evasionFreeFlip=false;note(g,`→ ${NAMES[h.role]} passa.`);advanceHeroTurn(g);return true}
function eatApple(g,h,slotIndex){const slot=h?.bag?.[slotIndex];if(!['playing','restoring'].includes(g.state)||h.role!==g.activeRole||h.actions<1||h.hp<=0||h.hp>=h.maxHp||slot?.item!=='apple'||slot.count<1)return false;const healed=Math.min(APPLE_HEAL,h.maxHp-h.hp);h.hp+=healed;h.actions--;slot.count--;if(!slot.count)h.bag[slotIndex]=null;g.telemetry.items.applesEaten[h.role]++;g.telemetry.items.appleHealing[h.role]+=healed;boardAudit(g,'APPLE_EATEN',{hero:h.role,slot:slotIndex,healed,remaining:slot.count||0});note(g,`🍎 ${NAMES[h.role]} mangia una mela: +${healed} HP (1 azione).`);return true}
function removeOneWound(h){const deckIndex=h.deck.indexOf('wound');if(deckIndex<0)return false;h.deck.splice(deckIndex,1);for(const zone of [h.hand,h.draw,h.discard]){const index=zone.indexOf('wound');if(index>=0){zone.splice(index,1);break}}return true}
function bagStackable(id){return id==='apple'||id==='resurrection_rune'||!!TREASURE_ITEMS[id]&&TREASURE_ITEMS[id].kind!=='equipment'}
function addBagItem(h,id,n=1,diff=null){if(bagStackable(id)){const slot=h.bag.find(s=>s&&s.item===id&&(s.diff||null)===(diff||null));if(slot){slot.count+=n;return true}}const index=h.bag.findIndex(s=>!s);if(index<0)return false;h.bag[index]={item:id,count:n,diff:diff||null};return true}
function canTakeBagItem(h,id){return bagStackable(id)&&h.bag.some(s=>s&&s.item===id)||h.bag.some(s=>!s)}
function lootEligibleHeroes(g,item){return g.party.filter(h=>(!item.role||h.role===item.role)&&(!item.roles||item.roles.includes(h.role)))}
function rollForLoot(g,uid){const loot=g.pendingLoot?.find(e=>e.uid===uid),item=TREASURE_ITEMS[loot?.item];if(!loot)return false;const eligible=lootEligibleHeroes(g,item).filter(h=>canTakeBagItem(h,loot.item));if(eligible.length<2)return false;let rolls,top,winners;do{rolls=eligible.map(h=>({role:h.role,roll:1+Math.floor(Math.random()*20)}));top=Math.max(...rolls.map(r=>r.roll));winners=rolls.filter(r=>r.roll===top)}while(winners.length>1);boardAudit(g,'LOOT_ROLL',{item:loot.item,rolls,winner:winners[0].role});note(g,`🎲 Contesa ${item.name}: ${rolls.map(r=>`${NAMES[r.role]} ${r.roll}`).join(' · ')} → vince ${NAMES[winners[0].role]}.`);return assignLoot(g,uid,winners[0].role)}
function consumeBagItem(g,h,slotIndex){const slot=h.bag[slotIndex],id=slot?.item;if(slot&&slot.count>1)slot.count--;else h.bag[slotIndex]=null;g.telemetry.items.itemsUsed[id]=(g.telemetry.items.itemsUsed[id]||0)+1;boardAudit(g,'BAG_ITEM_USED',{hero:h.role,item:id,slot:slotIndex})}
function discardBagItem(g,h,slotIndex){const slot=h?.bag?.[slotIndex],item=TREASURE_ITEMS[slot?.item];if(!slot||!item)return false;h.bag[slotIndex]=null;g.telemetry.items.discarded=(g.telemetry.items.discarded||0)+1;boardAudit(g,'BAG_ITEM_DISCARDED',{hero:h.role,item:slot.item,count:slot.count||1,slot:slotIndex});note(g,`🗑 ${NAMES[h.role]} elimina ${item.name} dalla Bag.`);return true}
function useBagItem(g,h,slotIndex,targetRole=null){const id=h?.bag?.[slotIndex]?.item,item=TREASURE_ITEMS[id],turnKey=`${g.encounter}:${g.round}:${g.state}`;if(!item||item.kind==='equipment'||!['playing','restoring'].includes(g.state)||h.role!==g.activeRole||h.hp<=0)return false;const needsAction=!['bronze_whetstone','bronze_crystal','silver_runestone','silver_sacred_crystal','silver_haste'].includes(id);if(needsAction&&h.actions<1)return false;if(id.includes('potion')&&!id.includes('evasion')&&id!=='silver_haste'&&h.hp>=h.maxHp)return false;if(id==='silver_haste'){if(h.actions>=CONFIG.actionsPerRound||h.hasteRound===turnKey)return false;h.actions++;h.hasteRound=turnKey}else if(id==='bronze_whetstone'||id==='silver_runestone'){if(h.itemWeaponBonus)return false;h.itemWeaponBonus=2}else if(id==='bronze_crystal'||id==='silver_sacred_crystal'){if(h.itemSpellBonus)return false;h.itemSpellBonus=2}else if(id==='bronze_healing_potion'||id==='silver_major_potion'){h.actions--;const amount=id==='bronze_healing_potion'?4:5;h.hp+=Math.min(amount,h.maxHp-h.hp)}else if(id==='bronze_bandage'||id==='silver_purifying_remedy'){if(!removeOneWound(h)&&h.hp>=h.maxHp)return false;h.actions--;h.hp+=Math.min(id==='bronze_bandage'?1:2,h.maxHp-h.hp)}else if(id==='bronze_bomb'||id==='silver_bomb'){if(!aliveEnemies(g).length)return false;h.actions--;const power=id==='bronze_bomb'?2:3;for(const enemy of [...aliveEnemies(g)])damage(g,h.role,enemy,power);checkVictory(g)}else if(id==='bronze_evasion'){h.actions--;h.itemEvasion=true}else if(id==='silver_ward'){h.actions--;h.itemWard=3}else if(id==='silver_revival'){const target=g.party.find(hero=>hero.role===targetRole&&hero.hp<=0)||g.party.find(hero=>hero.hp<=0);if(!target)return false;h.actions--;target.hp=Math.min(3,target.maxHp);boardAudit(g,'HERO_REVIVED_BY_ITEM',{hero:h.role,target:target.role,hp:target.hp})}else return false;consumeBagItem(g,h,slotIndex);note(g,`🎒 ${NAMES[h.role]} usa ${item.name}.`);return true}
function equipmentFromItem(id,acqDiff){const item=TREASURE_ITEMS[id];return{id,name:item.name,damage:item.damage,block:item.block,healingBonus:item.healingBonus,spellDamageBonus:item.spellDamageBonus,fireDamageBonus:item.fireDamageBonus,frostDamageBonus:item.frostDamageBonus,holyPulseBonus:item.holyPulseBonus,twoHanded:!!item.twoHanded,power:item.power,itemId:id,acqDiff:acqDiff||null}}
function migrateMageDamageLabels(h){if(h?.role!=='mage')return;for(const slot of ['staff','wand']){const equipped=h[slot],item=TREASURE_ITEMS[equipped?.itemId];if(item)equipped.name=item.name}}
function storeEquipmentIds(h,slotIndex,ids){h.bag[slotIndex]=null;for(const id of ids){const index=h.bag.findIndex(slot=>!slot);if(index<0)return false;h.bag[index]={item:id,count:1}}return true}
function equipBagItem(g,h,slotIndex,hand='left'){const id=h?.bag?.[slotIndex]?.item,item=TREASURE_ITEMS[id],roleOk=item&&(item.role?item.role===h.role:item.roles?item.roles.includes(h.role):false),shieldHero=['warrior','paladin'].includes(h.role);if(!item||item.kind!=='equipment'||!roleOk||g.state!=='restoring'||h.role!==g.activeRole||h.actions<1||shieldHero&&item.slot==='offhand'&&h.twoHanded)return false;const next=equipmentFromItem(id,h?.bag?.[slotIndex]?.diff),returning=[];if(shieldHero){if(item.slot==='weapon'){if(h.weapon?.itemId)returning.push(h.weapon.itemId);if(item.twoHanded&&h.offhand?.itemId)returning.push(h.offhand.itemId)}else if(h.offhand?.itemId)returning.push(h.offhand.itemId)}else if(['healer','mage','warlock'].includes(h.role)){const current=item.slot==='staff'?h.staff:h.wand;if(current?.itemId)returning.push(current.itemId)}else{const current=h.daggers[hand];if(current?.itemId)returning.push(current.itemId)}const available=h.bag.filter((slot,index)=>index===slotIndex||!slot).length;if(returning.length>available)return false;if(!storeEquipmentIds(h,slotIndex,returning))return false;if(shieldHero){if(item.slot==='weapon'){h.weapon=next;h.twoHanded=next.twoHanded;if(next.twoHanded)h.offhand=null}else h.offhand=next;h.board.equipment=[h.weapon?.id,h.offhand?.id].filter(Boolean)}else if(['healer','mage','warlock'].includes(h.role)){if(item.slot==='staff')h.staff=next;else h.wand=next}else h.daggers[hand]=next;h.actions--;g.telemetry.items.equipmentChanged++;boardAudit(g,'TREASURE_EQUIPPED',{hero:h.role,item:id,slot:item.slot,hand:h.role==='rogue'?hand:null,actionCost:1,returned:returning});note(g,`✦ ${NAMES[h.role]} equipaggia ${item.name} (1 azione).`);return true}
function useResurrectionRune(g,h,slotIndex){const slot=h?.bag?.[slotIndex];if(!['playing','restoring'].includes(g.state)||h.hp>0||slot?.item!=='resurrection_rune'||slot.count<1)return false;h.hp=Math.max(1,Math.ceil(h.maxHp/2));h.actions=CONFIG.actionsPerRound;slot.count--;if(slot.count<1)h.bag[slotIndex]=null;g.telemetry.revival.heroes++;g.telemetry.revival.byHero[h.role]=(g.telemetry.revival.byHero[h.role]||0)+1;boardAudit(g,'HERO_REVIVED_BY_RUNE',{hero:h.role,hp:h.hp,runesLeft:slot?slot.count:0});note(g,`✝ ${NAMES[h.role]} usa una Runa della Resurrezione: torna con ${h.hp} HP.`);return true}
function bagSlotHtml(h,slot,index,active){if(!slot)return`<div class="hero-bag-slot"><strong>Slot ${index+1}</strong><small>Vuoto</small></div>`;const shell=(id,tier,name,text,controls)=>`<div class="hero-bag-slot treasure ${tier}" data-bag-item="${id}" data-bag-role="${h.role}" data-bag-slot="${index}"><img class="bag-item-icon" src="assets/icons/${bagItemIconFile(id)}" alt=""><strong>${name}</strong><small class="bag-item-effect">${text}</small><div class="bag-item-actions">${controls}<button class="bag-trash" data-trash-item="${index}" data-bag-role="${h.role}" title="Elimina dalla Bag" aria-label="Elimina ${name}">🗑</button></div></div>`,usableState=['playing','restoring'].includes(game.state);if(slot.item==='apple')return shell('apple','apple',`Mela ×${slot.count}`,'Cura · vita · azione',`<button data-eat-apple="${index}" data-bag-role="${h.role}" ${!active||!usableState||h.actions<1||h.hp>=h.maxHp?'disabled':''}>Usa</button>`);if(slot.item==='resurrection_rune')return shell(slot.item,'base',`Runa ×${slot.count}`,'Rialza · metà vita · recupero',`<button data-use-rune="${index}" data-bag-role="${h.role}" ${game.state==='restoring'&&h.hp<=0?'':'disabled'}>Usa</button>`);const item=TREASURE_ITEMS[slot.item],free=['bronze_whetstone','bronze_crystal','silver_runestone','silver_sacred_crystal','silver_haste'].includes(slot.item),disabled=!active||!usableState||!free&&h.actions<1,dead=game.party.filter(hero=>hero.hp<=0);if(item.kind==='equipment'){const canEquip=game.state==='restoring'&&active&&h.actions>0,controls=h.role==='rogue'?`<button data-equip-item="${index}" data-equip-hand="left" ${canEquip?'':'disabled'}>Sinistra</button><button data-equip-item="${index}" data-equip-hand="right" ${canEquip?'':'disabled'}>Destra</button>`:`<button data-equip-item="${index}" ${canEquip?'':'disabled'}>Equipaggia</button>`;return shell(slot.item,item.tier.toLowerCase(),item.name,item.text,controls)}const controls=slot.item==='silver_revival'&&dead.length?dead.map(target=>`<button data-use-item="${index}" data-item-target="${target.role}" ${disabled?'disabled':''}>Rialza ${NAMES[target.role]}</button>`).join(''):`<button data-use-item="${index}" ${disabled||slot.item==='silver_revival'?'disabled':''}>Usa</button>`;return shell(slot.item,item.tier.toLowerCase(),`${item.name}${slot.count>1?` ×${slot.count}`:''}`,item.text,controls)}
function heroBagPanel(h){const active=h.role===game.activeRole,apples=h.bag.reduce((total,slot)=>total+(slot?.item==='apple'?slot.count:0),0),items=h.bag.filter(slot=>slot&&slot.item!=='apple').length;return`<details class="hero-bag" data-bag-role="${h.role}" ${h.bagOpen?'open':''}><summary><span>Bag</span><span>🍎 ×${apples} · ${items} oggetti · ${h.bag.length} slot</span></summary><div class="bag-slots">${h.bag.map((slot,index)=>bagSlotHtml(h,slot,index,active)).join('')}</div></details>`}
function drawLootItem(g,tier,role=null){if(tier==='GOLD'||tier==='GOLD2'){const byRole=tier==='GOLD2'?GOLD2_LOOT_BY_ROLE:GOLD_LOOT_BY_ROLE,deck=g.lootDecks[tier][role];if(!deck.length)deck.push(...shuffle([...byRole[role]]));return deck.pop()}const pool=tier==='BRONZE'?BRONZE_LOOT_POOL:SILVER_LOOT_POOL,deck=g.lootDecks[tier];if(!deck.length)deck.push(...shuffle([...pool]));return deck.pop()}
function revealTreasureLoot(g,boxTier){const poolTier=effectiveLootTier(g,boxTier),perRole=poolTier==='GOLD'||poolTier==='GOLD2',lootRoles=shuffle([...(g.party||[])]).slice(0,3).map(hero=>hero.role),ids=perRole?lootRoles.map(role=>drawLootItem(g,poolTier,role)):Array.from({length:3},()=>drawLootItem(g,poolTier)),diff=g.difficulty||'normale';g.pendingLoot=ids.map((item,index)=>({uid:`${poolTier}-${g.encounter}-${Date.now()}-${index}`,item,diff}));g.pendingLootTier=boxTier;g.telemetry.items.treasuresOpened[poolTier]=(g.telemetry.items.treasuresOpened[poolTier]||0)+1;boardAudit(g,'TREASURE_CONTENT_REVEALED',{boxTier,poolTier,diff,items:ids});note(g,`🎁 Cassa ${lootTierLabel(boxTier)}: rivelate ${ids.map(id=>TREASURE_ITEMS[id].name).join(', ')}.`)}
