const RECOVERY_ACTIONS=99;
// BARRA HP JUICY: fill verde istantaneo + ghost rosso che insegue (eased via rAF, sopravvive al re-render distruttivo) + flash al colpo.
const HP_DISP={},HP_LAST={};
function hpBarHtml(key,hp,max,noNum){hp=Math.max(0,hp);return`<div class="hpbar-wrap">${noNum?'':`<b class="hpbar-num">${hp}/${max}</b>`}<div class="hpbar" data-hp-key="${key}" data-hp="${hp}" data-hpmax="${max||1}"><div class="hpbar-ghost"></div><div class="hpbar-fill"></div></div></div>`}
function enemyDisplayName(e){return enemyLabel(e).replace(/\s+\d+$/,'')}
function spawnHpFloat(bar,delta){const r=bar.getBoundingClientRect();if(!r.width)return;const el=document.createElement('div');el.className='dmg-float '+(delta>0?'dmg':'heal');el.textContent=delta>0?'-'+delta:'+'+(-delta);el.style.left=(r.left+r.width/2)+'px';el.style.top=(r.top-2)+'px';document.body.appendChild(el);setTimeout(()=>el.remove(),850)}
function tickHpBars(){for(const bar of document.querySelectorAll('.hpbar')){const key=bar.dataset.hpKey,hp=Math.max(0,+bar.dataset.hp),max=+bar.dataset.hpmax||1,cur=hp/max*100,fill=bar.querySelector('.hpbar-fill'),ghost=bar.querySelector('.hpbar-ghost');if(!fill||!ghost)continue;if(HP_DISP[key]==null)HP_DISP[key]=cur;const prev=HP_LAST[key];if(prev!=null&&hp!==prev&&Number.isFinite(hp)&&Number.isFinite(prev)){spawnHpFloat(bar,prev-hp);bar.classList.remove('hp-hit','hp-heal');void bar.offsetWidth;bar.classList.add(prev-hp>0?'hp-hit':'hp-heal')}HP_LAST[key]=hp;let d=HP_DISP[key];if(Math.abs(d-cur)<0.4)d=cur;else d=cur+(d-cur)*0.86;HP_DISP[key]=d;fill.style.width=Math.min(d,cur)+'%';ghost.style.width=Math.max(d,cur)+'%';ghost.classList.toggle('heal',d<cur-0.01)}requestAnimationFrame(tickHpBars)}
if(typeof requestAnimationFrame!=='undefined')requestAnimationFrame(tickHpBars);
// DECKBUILDING Fase 1: collezione (possedute) vs mazzo (12 in gioco). Editor al Campo/Recupero. Reward->collezione = Fase 1.5.
const DECK_CAP=12,DECK_COPY_MAX=3;
function ensureCollection(h){if(h.collection)return;const cfg=h.board?.config;h.collection=[...(h.deck?.length?h.deck:cfg?.startingDeck||[])].filter(c=>c!=='wound')}
function stripWounds(h){for(const k of['deck','draw','hand','discard'])if(Array.isArray(h[k]))h[k]=h[k].filter(c=>c!=='wound')}
function deckAvailable(h){ensureCollection(h);const a={};h.collection.forEach(c=>a[c]=(a[c]||0)+1);h.deck.forEach(c=>{if(a[c])a[c]--});return a}
function deckRemoveCardBuild(g,h,card){const i=h.deck.indexOf(card);if(i<0)return false;h.deck.splice(i,1);for(const k of['draw','discard','hand']){const j=(h[k]||[]).indexOf(card);if(j>=0){h[k].splice(j,1);break}}boardAudit(g,'DECK_REMOVE',{hero:h.role,card,size:h.deck.length});return true}
function deckAddCardBuild(g,h,card){ensureCollection(h);const inDeck=h.deck.filter(c=>c===card).length;if(h.deck.length>=DECK_CAP||inDeck>=DECK_COPY_MAX||!deckAvailable(h)[card])return false;h.deck.push(card);(h.draw=h.draw||[]).push(card);boardAudit(g,'DECK_ADD',{hero:h.role,card,size:h.deck.length});return true}
