function treasureLootPanel(g){const tier=g.pendingLootTier,cards=g.pendingLoot||[];return`<section class="hero loot-panel ${tier?.toLowerCase()}"><h2>Cassa ${lootTierLabel(tier)} aperta</h2><p>Distribuisci tutte le 3 carte nelle Bag oppure lasciale nella stanza.</p><div class="loot-cards">${cards.map(entry=>{const item=TREASURE_ITEMS[entry.item],heroes=lootEligibleHeroes(g,item),takers=heroes.filter(h=>canTakeBagItem(h,entry.item));return`<article class="loot-card ${tier.toLowerCase()}"><span>${lootTierLabel(tier)}</span><h3>${item.name}</h3><p>${item.text}</p><div>${heroes.map(h=>`<button data-loot="${entry.uid}" data-loot-role="${h.role}" ${canTakeBagItem(h,entry.item)?'':'disabled'}>A ${NAMES[h.role]}</button>`).join('')}${takers.length>=2?`<button class="loot-roll" data-roll-loot="${entry.uid}">🎲 Contendi · Roll D20</button>`:''}<button class="secondary" data-leave-loot="${entry.uid}">Lascia</button></div></article>`}).join('')}</div></section>`}
