const LEGACY_CARD_SPECIALIZATIONS={healer:{quick_heal:['holy'],slow_heal:['holy'],bandage:['holy'],holy_pulse:['holy'],holy_shield:['holy'],holy_fire:['holy'],divine_strike:['holy'],holy_strike:['holy']}};
function specializationLabel(role,affinities=[]){const labels=[...new Set(affinities.map(branch=>SPECIALIZATION_LABELS[role]?.[branch]||branch))];return labels.length?labels.join(' / '):'Base / condivisa'}
function cardSpecialization(role,card){const data=collectionTalentData(role),affinities=data?.cards?.[card]||LEGACY_CARD_SPECIALIZATIONS[role]?.[card]||[];return specializationLabel(role,affinities)}
function freeCollectionBranchCards(h,branch){const data=collectionTalentData(h.role),available=deckAvailable(h),cards=[];if(!data)return cards;for(const[card,count]of Object.entries(available))if(count>0&&(data.cards[card]||[]).includes(branch))for(let n=0;n<count;n++)cards.push(card);return cards}
function collectionTalentOption(h,id){const data=collectionTalentData(h.role),target=data?.affinity[id]?.[0],source=data?.branches.find(branch=>branch!==target);if(!data||!target||!source)return null;const cards=freeCollectionBranchCards(h,source),synthetic=Object.keys(data.cards).find(card=>(data.cards[card]||[]).includes(target)&&data.available(h,id,card));return{data,target,source,cards,synthetic,available:cards.length>=2&&!!synthetic}}
function investCollectionTalent(g,h,id){const option=collectionTalentOption(h,id);if(!option?.available)return false;const spent=option.cards.slice(0,2);if(!option.data.invest(g,h,id,option.synthetic))return false;for(const card of spent){const index=h.collection.indexOf(card);if(index>=0)h.collection.splice(index,1)}boardAudit(g,'COLLECTION_TALENT_CONVERTED',{hero:h.role,source:option.source,target:option.target,cards:spent,talent:id});note(g,`↻ ${spent.map(card=>NAMES[card]||card).join(' + ')} dalla Collezione → ${option.data.talents[id].name}.`);return true}
function affinityIcons(affinity=[]){return affinity.map(icon=>icon==='shield'?'🛡':icon==='sword'?'⚔':icon==='holy'?'✚':icon==='shadow'?'◉':icon==='heal'?'✚':icon==='damage'?'✦':icon==='assassination'?'🗡':'◈').join('')}
function rogueCanPlay(){return true}
function priestCanPlay(h,card,target=null){const directHeal=['flash_heal','greater_heal','binding_heal','holy_nova','prayer_of_mending'].includes(card)||card==='penance'&&target?.role;if(h.shadowform&&directHeal)return false;return true}
function warriorCanPlay(h,card){if(['shield_slam','shield_protection','concussion_blow'].includes(card))return !h.twoHanded&&!!h.offhand;if(card==='whirlwind')return !!h.twoHanded;return true}
function flipWarrior(){return false}
function flipRogue(g,h){const free=g.state==='playing'&&!!h.evasionFreeFlip;if(!['playing','restoring'].includes(g.state)||!free&&h.actions<1||h.preparationPending)return false;const next=h.board.position.card==='FRONT'?'BEHIND':'FRONT';if(free)h.evasionFreeFlip=false;else{h.actions--;g.telemetry.rogue.actionsSpentOnFlip++}h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;g.telemetry.rogue.flips++;setPosition(g,h,next);note(g,`↔ Rogue passa in ${next} (${free?`gratis con ${NAMES.evasion}`:'1 azione'}).`);return true}
// ponytail: free flip usabile finché restano azioni nel turno; non tiene aperto il turno (niente Pass forzato ogni giro). Ceiling: non puoi flippare dopo aver speso l'ultima azione — flippa prima.
