function toggleWarriorTechnique(g,h,card,index){if(!['sword','rend','sweeping_strikes','shield_slam','concussion_blow','whirlwind','sunder_armor'].includes(card)||h.hand[index]!==card||!warriorCanPlay(h,card)||g.state!=='playing')return false;const same=h.warriorTechniqueArmed===card&&h.warriorTechniqueIndex===index;h.warriorTechniqueArmed=same?null:card;h.warriorTechniqueIndex=same?null:index;const shield=['shield_slam','concussion_blow'].includes(card);note(g,h.warriorTechniqueArmed?`◇ ${NAMES[card]} agganciata a ${shield?'Shield':'Weapon'} (0 azioni).`:`○ ${NAMES[card]} rimessa in mano.`);return true}
function consumeWarriorTechnique(g,h,card){const selected=h.warriorTechniqueIndex,index=h.hand[selected]===card?selected:h.hand.indexOf(card);if(index<0)return false;h.hand.splice(index,1);h.discard.push(card);h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;g.telemetry.actionsPlayed.warrior[card]=(g.telemetry.actionsPlayed.warrior[card]||0)+1;boardAudit(g,'TECHNIQUE_ATTACHED',{hero:'warrior',equipment:['parry','shield_slam','concussion_blow'].includes(card)?'SHIELD':'WEAPON',technique:card});return true}
function meleeDamageBonus(h,consume=false){if(!h)return 0;if(!Array.isArray(h.battleShoutStacks))h.battleShoutStacks=Array.from({length:Math.min(2,h.meleeBonus||0)},()=>3);const bonus=h.battleShoutStacks.length;if(consume){h.battleShoutStacks=h.battleShoutStacks.map(charges=>charges-1).filter(Boolean);h.meleeBonus=h.battleShoutStacks.length}else h.meleeBonus=bonus;return bonus}
function consumeBattleShout(h,hits=1){if(!meleeDamageBonus(h))return;h.battleShoutStacks=h.battleShoutStacks.map(charges=>charges-Math.max(1,hits)).filter(charges=>charges>0);h.meleeBonus=h.battleShoutStacks.length}
function clearBattleShout(h){h.battleShoutStacks=[];h.meleeBonus=0}
function sunderArmorBonus(target){if(!Array.isArray(target.sunderArmorStacks))target.sunderArmorStacks=Array.from({length:Math.min(2,target.sunderArmor||0)},()=>3);target.sunderArmor=target.sunderArmorStacks.length;return target.sunderArmor}
function consumeSunderArmor(target){if(!sunderArmorBonus(target))return;target.sunderArmorStacks=target.sunderArmorStacks.map(charges=>charges-1).filter(Boolean);target.sunderArmor=target.sunderArmorStacks.length}
function physicalDamage(g,role,target,n){const dealt=damage(g,role,target,n+sunderArmorBonus(target));if(dealt)consumeSunderArmor(target);return dealt}
function combatGridActionAllowed(g,role,action,targetValue){return !window.COMBAT_GRID_INTEGRATED||window.combatGridPatternAllows?.(g,role,action,targetValue)!==false}
function combatGridEnemiesForAction(g,role,action){return window.COMBAT_GRID_INTEGRATED&&window.combatGridPatternEnemies?window.combatGridPatternEnemies(g,role,action):[...aliveEnemies(g)]}
function warriorShieldBlock(h){return h&&!h.twoHanded&&h.offhand?(h.offhand.block||0)+(h.talents?.shield_wall||0):0}
function paladinShieldBlock(h){return h?.role==='paladin'&&h.offhand?(h.offhand.block||0)+(h.talents?.redoubt||0):0}
