  if(friendlyCards.includes(card)&&(!aliveHeroes(g).includes(target)||!combatGridActionAllowed(g,'warrior',card,targetValue)))return false;
  if(card==='shield_protection'&&!warriorShieldBlock(h)||card==='battle_shout'&&meleeDamageBonus(target)>=2)return false;
