  spend(h,card);g.telemetry.actionsPlayed.warrior[card]=(g.telemetry.actionsPlayed.warrior[card]||0)+1;if(destination){if(window.COMBAT_GRID_INTEGRATED&&g===game&&!g.benchmarkMode)g.combatGridSlide={role:h.role,from:{...h.combatGridPos},to:{...destination}};h.combatGridPos={...destination}}
  const base=(h.weapon?.damage||1)+(h.itemWeaponBonus||0)+meleeDamageBonus(h),critical=h.criticalArmed&&h.hand.includes('critical'),taunt=enemy=>{provokeEnemy(g,enemy,'warrior');const block=h.talents?.improved_taunt||0;if(block)h.shield+=block};let dealt=0,hits=0;
  if(card==='charge'){dealt=physicalDamage(g,'warrior',target,base+(critical?1:0));hits=1;taunt(target);note(g,`➜ Charge: ${dealt} danni · Taunt${h.talents?.improved_taunt?` · +${h.talents.improved_taunt} Block`:''}.`)}
  else if(card==='taunt'){taunt(target);note(g,`📣 Taunt: ${enemyLabel(target)} attaccherà il Guerriero${h.talents?.improved_taunt?` · +${h.talents.improved_taunt} Block`:''}.`)}
