  if(card==='lay_on_hands'){if(!ally||h.layOnHandsEncounter===g.encounter)return false;discard();h.actions--;played();h.layOnHandsEncounter=g.encounter;const value=paladinHeal(g,h,ally,ally.maxHp,card),removed=clearOnePriestDebuff(ally);note(g,`✚ Lay on Hands cura ${NAMES[ally.role]} di ${value}${removed?` e rimuove ${removed}`:''}.`);return true}
  if(card==='righteous_defense'){if(!enemy)return false;discard();h.actions--;played();provokeEnemy(g,enemy,'paladin');h.shield++;g.telemetry.paladin.taunts++;note(g,`🛡 Righteous Defense: ${enemyLabel(enemy)} provoca il Paladino · +1 Block.`);return true}
