  if(card==='consecration'||card==='avengers_shield'){if(!enemies.length)return false;discard();h.actions--;played();const targets=card==='avengers_shield'?enemies.slice(0,3):enemies,power=card==='consecration'?1+(h.talents?.improved_consecration||0):2;let total=0;for(const foe of targets){total+=damage(g,'paladin',foe,power);if(card==='avengers_shield')provokeEnemy(g,foe,'paladin')}g.telemetry.paladin.damage+=total;if(card==='avengers_shield')g.telemetry.paladin.taunts+=targets.length;note(g,`✦ ${NAMES[card]}: ${power} Holy a ${targets.length} nemici.`);checkVictory(g);return true}
