function tickShadowWordPain(g,e){const priest=g.party.find(hero=>hero.role==='healer'&&hero.hp>0);if(!priest||!e?.shadowWordPainCharges||e.hp<=0)return 0;const bonus=e.shadowWordPainBonus||0;e.shadowWordPainBonus=0;e.shadowWordPainCharges--;const value=withIndirectDamage(e,()=>priestShadowDamage(g,priest,e,1+bonus,'shadow_word_pain'));note(g,`◉ Shadow Word: Pain: ${value} danno a ${enemyLabel(e)} · ${e.shadowWordPainCharges} cariche.`);checkVictory(g);return value}
