  const h=reward.hero,a=reward.ability,talentId=choice?.startsWith('talent:')?choice.slice(7):null,spent=h.role==='warrior'&&talentId?investWarriorTalent(g,h,talentId,a):h.role==='healer'&&talentId?investPriestTalent(g,h,talentId,a):h.role==='rogue'&&talentId?investRogueTalent(g,h,talentId,a):h.role==='mage'&&talentId?investMageTalent(g,h,talentId,a):h.role==='paladin'&&talentId?investPaladinTalent(g,h,talentId,a):h.role==='warlock'&&talentId?investWarlockTalent(g,h,talentId,a):false;
