function abilityTrack(h,a){const value=h.mastery[a]||0,level=boardLevel(value),steps=Array.from({length:6},(_,i)=>`<span class="mastery-step ${i===value?'current':''} ${i===2||i===5?'threshold':''}">${i}${i===2?'<small>L2</small>':i===5?'<small>L3</small>':''}</span>`).join(''),texts=ABILITY_TEXT[a]||['TBD','TBD','TBD'];return`<article class="ability-track"><header><strong>${NAMES[a]||a}</strong><b>L${level}</b></header><div class="mastery-line">${steps}</div><ol>${texts.map((t,i)=>`<li class="${i+1===level?'active':''}">L${i+1}: ${t}</li>`).join('')}</ol></article>`}
function syncHandSlots(h){h.handSlots||=[];const pool=[...h.hand];for(let i=0;i<h.handSlots.length;i++){const c=h.handSlots[i];if(c==null)continue;const idx=pool.indexOf(c);if(idx>=0)pool.splice(idx,1);else h.handSlots[i]=null}for(const c of pool){const e=h.handSlots.indexOf(null);if(e>=0)h.handSlots[e]=c;else h.handSlots.push(c)}while(h.handSlots.length&&h.handSlots[h.handSlots.length-1]==null&&h.handSlots.length>h.hand.length)h.handSlots.pop()}
const equipBagItemWithoutPaladin=equipBagItem;
equipBagItem=function(g,h,slotIndex,hand='left'){if(h?.role!=='paladin')return equipBagItemWithoutPaladin(g,h,slotIndex,hand);const id=h.bag?.[slotIndex]?.item,item=TREASURE_ITEMS[id],roleOk=item&&(item.role==='paladin'||item.roles?.includes('paladin'));if(!item||item.kind!=='equipment'||!roleOk||!['weapon','offhand'].includes(item.slot)||g.state!=='restoring'||h.role!==g.activeRole||h.actions<1)return false;const current=item.slot==='weapon'?h.weapon:h.offhand,returning=current?.itemId?[current.itemId]:[];if(!storeEquipmentIds(h,slotIndex,returning))return false;const next=equipmentFromItem(id,h?.bag?.[slotIndex]?.diff);if(item.slot==='weapon')h.weapon=next;else h.offhand=next;h.board.equipment=[h.weapon?.id,h.offhand?.id].filter(Boolean);h.actions--;g.telemetry.items.equipmentChanged++;boardAudit(g,'TREASURE_EQUIPPED',{hero:h.role,item:id,slot:item.slot,actionCost:1,returned:returning});note(g,`✦ Paladino equipaggia ${item.name} (1 azione).`);return true}
const WEAPON_POWER_LABEL={taunt_on_hit:'Provoca al colpo',interrupt_cast:'Interrompe Cast Lungo',whirlwind_fast:'Whirlwind costa 2 azioni',slow_heal_shield:'Greater Heal → 2 Shield',kill_heal:'Una kill cura 1 HP',poison_once:'1 Vile Poison a turno',free_flip_once:'Movimento gratis a turno'};
function weaponPowerChips(h){const seen=new Set(),chips=[];for(const eq of [h.weapon,h.offhand,h.staff,h.wand,h.daggers?.left,h.daggers?.right]){const p=eq&&eq.power;if(p&&!seen.has(p)){seen.add(p);chips.push(`<span class="weapon-power" title="Abilità dell'arma (passiva)">✦ ${WEAPON_POWER_LABEL[p]||p}</span>`)}}return chips.join('')}
function weaponTier(eq){return((eq&&TREASURE_ITEMS[eq.itemId]?.tier)||'BASE').toLowerCase()}
function heroSlotEq(h,slot){return['warrior','paladin'].includes(h.role)?[h.weapon,h.offhand][slot]:h.role==='rogue'?[h.daggers?.left,h.daggers?.right][slot]:[h.staff,h.wand][slot]}
