function automaticEnemyTarget(g){const selected=targetOf(g,g.selectedTarget);if(aliveEnemies(g).includes(selected))return g.selectedTarget;const enemy=aliveEnemies(g)[0];if(enemy)g.selectedTarget=`enemy:x:${enemy.id}`;return g.selectedTarget}
function resolveWarriorTechniqueClick(g,h,index){const card=h.handSlots?.[index]??h.hand[index];if(!['sword','rend','sweeping_strikes','shield_slam','concussion_blow','whirlwind','sunder_armor'].includes(card)||!warriorCanPlay(h,card))return false;h.warriorTechniqueArmed=card;h.warriorTechniqueIndex=index;const resolved=['shield_slam','concussion_blow'].includes(card)?useShield(g,h,automaticEnemyTarget(g)):useSword(g,h,automaticEnemyTarget(g));if(!resolved){h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null}return resolved}
function resolveRogueTechniqueClick(g,h,index){const card=h.handSlots?.[index]??h.hand[index];if(!['backstab','eviscerate'].includes(card)||!rogueCanPlay(h,card))return false;h.rogueTechniqueArmed=card;h.rogueTechniqueIndex=index;const resolved=useDagger(g,h,automaticEnemyTarget(g),'left');if(!resolved){h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null}return resolved}
