function useMageWand(g,h,targetValue){if(g.state!=='playing'||h.actions<1)return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target)||!combatGridActionAllowed(g,'mage','mage_wand',targetValue))return false;h.actions--;const critical=h.criticalArmed&&h.hand.includes('critical'),dealt=damage(g,'mage',target,(h.wand?.damage||1)+(critical?1:0));if(critical)consumeCritical(g,h,'wand');g.telemetry.mage.damage+=dealt;note(g,`✦ ${h.wand?.name||'Wand'}${critical?' + Critico':''}: ${dealt} danni.`);checkVictory(g);return true}
