function useWarlockWand(g,h,targetValue){if(g.state!=='playing'||h.actions<1)return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target)||!combatGridActionAllowed(g,'warlock','warlock_wand',targetValue))return false;h.actions--;const value=damage(g,'warlock',target,h.wand?.damage||1);g.telemetry.warlock.damage+=value;note(g,`◉ ${h.wand?.name||'Wand'}: ${value} Shadow.`);checkVictory(g);return true}
