function specializationPrunePanel(h){const pending=h.pendingPrunes[0],cards=specializationPruneCandidates(h,pending.opposite),branch=h.role==='warrior'?(pending.branch==='sword'?'Aggressive':'Defense'):(pending.branch==='damage'?'Damage':'Heal');return`<section class="hero reward-card specialization-prune"><h2>Sfoltimento — ${NAMES[h.role]}</h2><p>Hai investito in <strong>${branch}</strong>. Puoi ritirare una carta della specializzazione opposta.</p><div class="reward-actions">${cards.map(card=>`<button data-prune-role="${h.role}" data-prune-card="${card}">Ritira ${NAMES[card]} · ×${h.deck.filter(value=>value===card).length}</button>`).join('')}<button class="secondary" data-prune-role="${h.role}" data-prune-skip>Non ritirare</button></div><small>Mazzo minimo: 8 carte${h.role==='healer'?' · almeno 2 carte Heal':''}.</small></section>`}
