const TEMPLE_COMPOSITION_CARDS=(()=>{let id=0,make=(f,t,n)=>Array.from({length:n},()=>({id:`temple-c${++id}`,f,t}));return[...make(1,0,13),...make(2,0,5),...make(0,1,7),...make(1,1,4),...make(2,1,1)]})();
