  const linked=templeOptions(g),fresh=linked.filter(room=>!temple.visited.includes(room.id)),ordered=[...fresh,...linked.filter(room=>temple.visited.includes(room.id))],preferred=['high-stairs','tongue-pools'].map(id=>fresh.find(room=>room.id===id)).filter(Boolean),options=(preferred.length===2?preferred:ordered).slice(0,2).map(room=>room.id);
