  if(composition.offers.length===2&&composition.offers[0].card.f===composition.offers[1].card.f&&composition.offers[0].card.t===composition.offers[1].card.t){const replacement=composition.draw.findIndex(card=>card.f!==composition.offers[0].card.f||card.t!==composition.offers[0].card.t);if(replacement>=0)[composition.offers[1].card,composition.draw[replacement]]=[composition.draw[replacement],composition.offers[1].card]}
