// La geografia è fissa: le tile dell'Overlord definiscono lo scontro, non la forma del Tempio.
function templeOptions(g){const current=fixedTempleRoom(g.temple?.currentId);return current?.links.map(id=>fixedTempleRoom(id)).filter(Boolean)||[]}
function templeBossReady(g){return (g.temple?.keys||[]).length>=2}
