  const source=currentExplorationRoom(x),composition=templeComposition(g),pendingComposition=composition.pending;let exit=pendingComposition?source.exits.find(item=>item.id===pendingComposition.exitId):source.exits[0];
  if(!exit){exit={id:`temple-${targetId}`,icons:{FIGHTER:0,TREASURE:0}};source.exits.push(exit)}
