render=function(){renderBeforePositionUnderWeapons();if(!game?.playerBoardEnabled)return;for(const column of document.querySelectorAll('.hero-column')){const bar=column.querySelector('.weapon-bar'),flip=column.querySelector('.turn-ctrl.flip[data-flip]');if(bar&&flip)bar.insertAdjacentElement('afterend',flip)}};

/* Pressione prolungata sulle carte Bag: stessa interazione delle Ability. */
(()=>{let timer,pressed;const dialog=document.createElement('dialog');dialog.className='ability-info item-info';dialog.innerHTML='<article class="ability-info-card"><button class="ability-info-close" type="button" aria-label="Chiudi">×</button><header class="ability-info-head"><i class="ability-info-icon" aria-hidden="true"></i><div><span class="ability-info-kicker">Dettagli oggetto</span><h2></h2></div></header><p class="ability-info-effect"></p><dl class="ability-info-rules"><div><dt>Categoria</dt><dd data-item-kind></dd></div><div><dt>Rarità</dt><dd data-item-tier></dd></div></dl><p class="ability-info-detail">Tieni premuto un altro oggetto per confrontarne subito le specifiche.</p><small class="ability-info-hint">Tocca fuori dalla scheda o premi × per chiudere.</small></article>';document.body.append(dialog);const clear=()=>{clearTimeout(timer);timer=null;pressed=null};function show(slot){const id=slot.dataset.bagItem,item=id==='apple'?{name:'Mela',kind:'consumable',tier:'BASE',text:'+2 HP · 1 azione'}:TREASURE_ITEMS[id];if(!item)return;dialog.querySelector('h2').textContent=item.name;dialog.querySelector('.ability-info-icon').style.backgroundImage=`url("assets/icons/${bagItemIconFile(id)}")`;dialog.querySelector('.ability-info-effect').textContent=item.text;dialog.querySelector('[data-item-kind]').textContent=item.kind==='equipment'?'Equipaggiamento':item.kind==='modifier'?'Modificatore':'Consumabile';dialog.querySelector('[data-item-tier]').textContent=item.tier==='GOLD2'?'GOLD+':item.tier;dialog.showModal();navigator.vibrate?.(20)}document.addEventListener('pointerdown',ev=>{const slot=ev.target.closest('.hero-bag-slot[data-bag-item]');if(!slot||ev.button>0)return;clear();pressed=slot;timer=setTimeout(()=>{if(pressed===slot){slot.dataset.itemLongPress='1';show(slot);setTimeout(()=>delete slot.dataset.itemLongPress,900)}},580)},true);document.addEventListener('pointerup',clear,true);document.addEventListener('pointercancel',clear,true);document.addEventListener('pointermove',clear,true);document.addEventListener('click',ev=>{const slot=ev.target.closest('.hero-bag-slot[data-bag-item][data-item-long-press]');if(slot){delete slot.dataset.itemLongPress;ev.preventDefault();ev.stopImmediatePropagation()}},true);document.addEventListener('contextmenu',ev=>{const slot=ev.target.closest('.hero-bag-slot[data-bag-item]');if(slot){ev.preventDefault();show(slot)}},true);dialog.querySelector('.ability-info-close').onclick=()=>dialog.close();dialog.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()})})();

function alignHeroActionPanels(){const columns=document.querySelector('.hero-columns');if(!columns)return;columns.style.removeProperty('--hero-action-height');const panels=[...columns.querySelectorAll('.hero-column:not(.overlord-column)>.hero')];if(panels.length<2)return;columns.style.setProperty('--hero-action-height',`${Math.ceil(Math.max(...panels.map(panel=>panel.getBoundingClientRect().height)))}px`)}
