function scriptEnsureBlocker(){if(!document.getElementById('scriptBlocker')){const b=document.createElement('div');b.id='scriptBlocker';b.className='script-blocker';document.body.append(b)}}
function scriptCleanup(){document.getElementById('scriptBlocker')?.remove();document.getElementById('scriptBox')?.remove();document.querySelector('#turnAnnounce[data-tutorial="true"]')?.remove();document.querySelectorAll('.script-live').forEach(e=>e.classList.remove('script-live'))}
function placeScriptBox(box,el){box.classList.remove('pos-top','pos-bottom');if(!el){box.style.top='';box.style.bottom='14px';box.style.transform='translateX(-50%)';return}const r=el.getBoundingClientRect(),bh=box.offsetHeight||90,m=12;let top=r.bottom+m;if(top+bh>innerHeight-m)top=r.top-m-bh;top=Math.max(m,Math.min(top,innerHeight-bh-m));box.style.top=top+'px';box.style.bottom='auto';box.style.transform='translateX(-50%)'}
function scriptShowStep(step,isAuto){scriptEnsureBlocker();document.querySelectorAll('.script-live').forEach(e=>e.classList.remove('script-live'));if(step.announce){document.getElementById('scriptBox')?.remove();showTurnAnnounce(step.announce);return}document.getElementById('turnAnnounce')?.remove();const el=step.sel&&step.sel();if(el){el.classList.add('script-live');if(step.tap){el.style.cursor='pointer';el.onclick=function(ev){ev.preventDefault();ev.stopPropagation();if(game._script)game._script._tap=true;render()}}try{el.scrollIntoView({block:'center',inline:'nearest',behavior:'smooth'})}catch(e){}}let box=document.getElementById('scriptBox');if(!box){box=document.createElement('div');box.id='scriptBox';box.className='script-box';document.body.append(box)}box.innerHTML=`<span class="script-arrow">${isAuto?'☠':'👉'}</span><span>${originalizeLore(step.text)}</span>`;placeScriptBox(box,el);setTimeout(()=>{if(document.getElementById('scriptBox')===box)placeScriptBox(box,step.sel&&step.sel())},420)}
function scriptDrive(){const sc=game._script;if(game.state!=='playing'||game.round>sc.maxRound){game._script=null;game._scriptDone=true;scriptCleanup();return}for(let guard=0;guard<40;guard++){if(sc.i>=sc.steps.length){game._script=null;game._scriptDone=true;scriptCleanup();return}if(sc.shownFor===sc.i&&sc.base&&sc.steps[sc.i].done&&sc.steps[sc.i].done(game,sc.base)){sc.i++;continue}const step=sc.steps[sc.i];if(step.pre&&!step.preDone){step.preDone=true;step.pre(game);render();return}if(step.who&&step.who!=='overlord'&&game.activeRole!==step.who){scriptCleanup();return}if(step.auto){scriptShowStep(step,true);if(!sc.autoScheduled){sc.autoScheduled=true;const at=sc.i;setTimeout(()=>{if(!game._script||game._script.i!==at)return;try{step.run&&step.run(game)}catch(e){}game._script.autoScheduled=false;game._script.i++;render()},step.delay||1600)}return}if(sc.shownFor!==sc.i){sc.shownFor=sc.i;sc.base={acts:scActs(step.who),pos:scPos(step.who),active:game.activeRole,showFriendly:game.showFriendly}}scriptShowStep(step,false);return}}
const renderBeforeScript=render;
render=function(){renderBeforeScript();if(!game||!game.tutorial||game._scriptDone){if(!game||!game._script)scriptCleanup();return}if(game._tourActive||document.getElementById('tourBox')||document.getElementById('tutMsgBox')){if(!game._script)scriptCleanup();return}if(!game._script&&game._scriptPending&&game.state==='playing'&&game.activeRole&&game.activeRole!=='enemies'){game._script={i:0,steps:buildTutorialScript(game.encounter),maxRound:game.encounter===2?2:1,clicked:false};game._scriptPending=false}if(!game._script){scriptCleanup();return}scriptDrive()};

