    dialog.querySelector('.ability-info-kicker').textContent=buff?'Buff attivo':'Debuff attivo';dialog.querySelector('h2').textContent=label;dialog.querySelector('.ability-info-effect').textContent=originalizeLore(rule?.[1]?.[1]||'Effetto temporaneo attivo sul bersaglio.');dialog.querySelector('[data-context-spec]').textContent=originalizeBranchLabel(rule?.[1]?.[0]||'Sistema combattimento');dialog.querySelector('[data-context-current]').textContent=buff?'Beneficio attivo':'Penalità attiva';dialog.querySelector('.ability-info-detail').textContent='Il valore sull’icona indica cariche, intensità o durata rimasta, a seconda dell’effetto.';dialog.querySelector('.context-info-steps').hidden=true;dialog.style.setProperty('--ability-info-icon',`url("assets/icons/${node.dataset.statusIcon}.svg")`);open();
