/* Recupero libero: si cambia Eroe senza consumare il turno e si chiude una volta sola. */
(()=>{
  const style=document.createElement('style');style.textContent=`
    .deck-editor>.recovery-phase{display:grid!important;grid-template-columns:auto minmax(0,1fr) auto;align-items:center}
    .recovery-hero-selector{display:flex;justify-content:center;gap:6px;min-width:0;overflow-x:auto;padding:2px}
    .recovery-hero-selector button{display:flex;align-items:center;gap:6px;min-width:112px;padding:5px 8px;border:1px solid #566655;border-radius:9px;background:#111914;color:#d4ddcf;text-align:left;cursor:pointer}
    .recovery-hero-selector button.active{border-color:#f0cf66;background:#3b3219;color:#fff2ad;box-shadow:0 0 0 2px #e7c75d2e}
    .recovery-hero-selector img{width:32px;height:32px;border-radius:6px;object-fit:cover}
    .recovery-hero-selector span,.recovery-hero-selector strong,.recovery-hero-selector small{display:block;min-width:0}
    .recovery-hero-selector strong{overflow:hidden;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.recovery-hero-selector small{margin-top:2px;font-size:8px}
    .recovery-finish{min-height:42px;padding:8px 14px;border:1px solid #e8cb62;border-radius:9px;background:linear-gradient(#e7ca68,#b99135);color:#191409;font-weight:900;cursor:pointer}
    @media(max-width:900px){.deck-editor>.recovery-phase{grid-template-columns:1fr}.recovery-hero-selector{justify-content:flex-start}.recovery-finish{width:100%}}
  `;document.head.append(style);
  const renderBeforeFreeRecovery=render;
  render=function(){renderBeforeFreeRecovery();const end=document.getElementById('end');if(end)end.onclick=()=>{if(game.playerBoardEnabled){if(game.state==='restoring')finishRecoveryTurn(game);else passHeroTurn(game)}else endRound(game);render()};if(!game?.playerBoardEnabled||game.state!=='restoring')return;const phase=document.querySelector('.recovery-phase');if(phase){phase.innerHTML=`<div><strong>Turno di Recupero</strong><small>Gestione libera: cambia Eroe quando vuoi.</small></div>${recoveryHeroSelector(game)}<button type="button" class="recovery-finish" data-recovery-finish>Fine recupero</button>`;phase.querySelectorAll('[data-recovery-hero]').forEach(button=>button.onclick=()=>{selectRecoveryHero(game,button.dataset.recoveryHero);render()});phase.querySelector('[data-recovery-finish]').onclick=()=>{finishRecoveryTurn(game);render()}}if(end){end.textContent='Fine recupero';end.disabled=false}}
})();
